cd /testbed && sed -n '85,115p' tokio/src/sync/broadcast.rs && patch -p1 <<'PATCH'
--- a/tokio/src/sync/broadcast.rs
+++ b/tokio/src/sync/broadcast.rs
@@ -667,7 +667,12 @@

     tail.rx_cnt = tail.rx_cnt.checked_add(1).expect("overflow");

-    let next = tail.pos;
+    // A closed channel's tail is one position past the closed marker.
+    let next = if tail.closed {
+        tail.pos.wrapping_sub(1)
+    } else {
+        tail.pos
+    };

     drop(tail);

@@ -897,6 +902,9 @@
     /// **after** it has resubscribed. This will not include elements that are
     /// in the queue of the current receiver. Consider the following example.
     ///
+    /// If the channel is closed, the next call to [`recv`](Self::recv) will
+    /// return [`RecvError::Closed`].
+    ///
     /// # Examples
     ///
     /// ```
PATCH
if [ $? -ne 0 ]; then exit 1; fi
cargo test --test sync_broadcast --features sync 2>&1 | tail -38
exit ${PIPESTATUS[0]}

